-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Builds the client-specific library environment and its saved-state bridges.

local Adapter = APR.NavigationAdapter
local Shared = APR.NavigationAdapter._helpers
local Call = Shared.Call
local Lib = Shared.Lib
local environment = Shared.environment

-- Capture the interface version before conversion. Passing select's results
-- directly would also pass later build fields as tonumber's base argument.
local _, _, _, interfaceVersion = Call(GetBuildInfo)
local interface = tonumber(interfaceVersion) or 0
local profile = interface >= 16000 and interface < 17000 and "forever"
    or (interface >= 100000 and "retail" or "unsupported")
local Data = Lib:New({
    profile = profile,
    environment = environment,
    waypoints = {
        guideProviderID = "apr",
        nativeSupportSetting = "APRSupportEnabled",
        automaticRefresh = "external",
        finalDestination = true,
    },
})
APR.NavigationData, APR.NavigationEngine = Data, Lib.Engine

function Adapter:GetBlockedRouteText(blockers, styled)
    local text, lines = Data:GetBlockedRouteText(blockers)
    if not styled or not lines or not APR.WrapTextWithAppearanceColor then return text, lines end
    local roles = { status = "error", passage = "title", requirement = "base", operator = "muted" }
    local rendered = {}
    for _, line in ipairs(lines) do
        rendered[#rendered + 1] = line.text ~= ""
                and APR:WrapTextWithAppearanceColor(line.text, "currentStep", roles[line.kind])
            or ""
    end
    return table.concat(rendered, "\n"), lines
end--[[APR_DIAG]]; Adapter.GetBlockedRouteText = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterData.lua:32:Adapter:GetBlockedRouteText#1", Adapter.GetBlockedRouteText)--[[/APR_DIAG]]

