function Data:GetBindPosition() return Adapter:GetBindPosition() end--[[APR_DIAG]]; Data.GetBindPosition = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterData.lua:49:Data:GetBindPosition#4", Data.GetBindPosition)--[[/APR_DIAG]]

function Data:GetBindLocationMapID()
    local position = self:GetBindPosition()
    return position and position.uiMapID
end--[[APR_DIAG]]; Data.GetBindLocationMapID = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterData.lua:51:Data:GetBindLocationMapID#5", Data.GetBindLocationMapID)--[[/APR_DIAG]]

function Data:IsBindLocationSupported() return self:GetBindPosition() ~= nil end--[[APR_DIAG]]; Data.IsBindLocationSupported = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterData.lua:56:Data:IsBindLocationSupported#6", Data.IsBindLocationSupported)--[[/APR_DIAG]]

function Data:UpdateHousingExitLocation() Adapter:UpdateHousingExitLocation() end--[[APR_DIAG]]; Data.UpdateHousingExitLocation = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterData.lua:58:Data:UpdateHousingExitLocation#7", Data.UpdateHousingExitLocation)--[[/APR_DIAG]]

APR.NavigationAdapter._helpers.Data = Data
APR.NavigationAdapter._helpers.profile = profile
